import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 sentValue) public {
        // Restrict sentValue to a reasonable range to avoid overflow
        sentValue = bound(sentValue, 0, 100 ether);
        // Ensure sender is not the test contract itself (avoids balance confusion)
        vm.assume(sender != address(this));
        // Ensure sender has sufficient balance for the value it sends
        vm.deal(sender, sentValue + 1 ether);
        uint256 balanceBefore = sender.balance;
        vm.prank(sender);
        try c.lockInGuess{value: sentValue}(bytes32(0)) {
            // If the call succeeds, the sender must have been charged exactly 1 ether.
            // This is the invariant of the reference contract.
            uint256 balanceAfter = sender.balance;
            // In the reference, msg.value is required to be 1 ether, so the decrease
            // must be exactly 1 ether (plus gas, which we disregard by checking the
            // non-strict inequality for the upper bound, but strictly for the lower bound).
            // A simpler exact property: the decrease in sender's balance must be at least 1 ether
            // because the reference always transfers 1 ether. The bug allows 0 ether,
            // so the decrease can be 0.
            assertTrue(balanceBefore - balanceAfter >= 1 ether);
        } catch {
            // If the call fails (e.g., because msg.value != 1 ether in the reference),
            // no invariant is violated.
        }
    }
}

