pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guessHash, uint8 blockDelta) public {
        // blockDelta: 0 = same block, 1 = next block, 2..255 = later blocks
        address solver = makeAddr("solver");

        // Give the solver 1 ether and let them lock in a guess
        vm.deal(solver, 1 ether);
        vm.startPrank(solver);
        c.lockInGuess{value: 1 ether}(guessHash);
        vm.stopPrank();

        // Move forward by blockDelta (0 = same block, 1 = next block, etc.)
        vm.roll(block.number + blockDelta);

        // Record balance before settling
        uint256 balanceBefore = solver.balance;

        // Attempt to settle
        vm.prank(solver);
        bool settled = false;
        try c.settle() returns (bool) {
            settled = true;
        } catch {
            settled = false;
        }

        uint256 balanceAfter = solver.balance;

        // If settlement executed without revert and the caller's balance increased,
        // it means the guess was correct and a 2 ether payout occurred.
        // In that case, blockDelta MUST be at least 1 (settlement in a strictly later block).
        // The reference contract enforces this; the buggy one allows blockDelta == 0.
        if (settled && balanceAfter > balanceBefore) {
            assertTrue(blockDelta >= 1);
        } else {
            assertTrue(true);
        }
    }
}

