import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(uint256 settlementBlockOffset) public {
        // Restrict offset so we only test same-block settlement (0) vs later blocks.
        // This keeps the domain wide while focusing on the block timing difference.
        settlementBlockOffset = bound(settlementBlockOffset, 0, 10);

        address sender = makeAddr("sender");
        bytes32 hash = bytes32(uint256(1));

        // Provide the required 1 ether for lockInGuess
        vm.deal(sender, 1 ether);

        // Record the block at which lockInGuess executes
        vm.prank(sender);
        c.lockInGuess{value: 1 ether}(hash);

        uint256 lockBlock = block.number;
        uint256 settleBlock = lockBlock + settlementBlockOffset;

        // Warp to the target settle block (same block if offset is 0)
        vm.roll(settleBlock);

        uint256 balanceBefore = sender.balance;

        // Call settle and capture whether it succeeded (did not revert)
        bool ok;
        vm.prank(sender);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = sender.balance;

        // If settlementBlockOffset == 0, we are in the SAME block.
        // In the reference contract, settle must revert (and never transfer funds),
        // so the balance must remain unchanged.
        // The buggy contract allows settlement and transfers 2 ether,
        // changing the balance. The invariant therefore fails on the bug.
        if (settlementBlockOffset == 0) {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

