pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 blockDelay) public {
        // Keep blockDelay in admissible range: at least 1 block after lockInGuess
        blockDelay = bound(blockDelay, 1, 256);

        // Fund the contract with 2 ether so it can pay out (initial 1 from ctor + 1 from lockInGuess)
        vm.deal(address(this), 4 ether);
        vm.deal(address(c), 2 ether);

        // Actor locks in a guess
        c.lockInGuess{value: 1 ether}(hash);

        // Advance blocks so settle is callable
        vm.roll(block.number + blockDelay);

        // Ensure the answer at the guess block matches the guess, so settlement pays out
        bytes32 answer = blockhash(block.number - blockDelay);
        if (answer == 0 || answer != hash) {
            // Cannot force a win; skip this run
            return;
        }

        uint256 balBefore = address(c).balance;
        c.settle();
        uint256 balAfter = address(c).balance;

        // Reference rule: contract balance must decrease by exactly 2 ether on a winning settle
        assertTrue(balBefore - balAfter == 2 ether);
    }
}
